"use client"

import * as React from "react"
import { cn } from "@/lib/utils"

export type StaggerFrom =
  | "first"
  | "last"
  | "center"
  | "random"
  | number
  | [number, number]

export type StaggerAxis = "x" | "y" | "all"

export interface StaggerParameters {
  start?: number
  from?: StaggerFrom
  grid?: [number, number]
  axis?: StaggerAxis
  reversed?: boolean
  ease?: (t: number) => number | string
  modifier?: (value: number) => number | string
}

export type StaggerValue =
  | number
  | string
  | [number, number]
  | [string, string]

/**
 * Parses numeric value and optional unit string.
 */
function parseUnitValue(val: number | string): { num: number; unit: string } {
  if (typeof val === "number") return { num: val, unit: "" }
  const match = val.match(/^([+-]?(?:\d+(?:\.\d+)?|\.\d+))(.*)$/)
  if (match) {
    return { num: Number.parseFloat(match[1]), unit: match[2] || "" }
  }
  return { num: Number.parseFloat(val) || 0, unit: "" }
}

/**
 * Comprehensive Anime.js v4 style stagger function.
 */
export function stagger(
  value: StaggerValue,
  parameters: StaggerParameters = {}
): (index: number, total: number) => number | string {
  const {
    start = 0,
    from = 0,
    grid,
    axis = "all",
    reversed = false,
    modifier,
  } = parameters

  return (index: number, total: number) => {
    let position = 0

    if (grid && grid.length === 2) {
      const [cols, rows] = grid
      const col = index % cols
      const row = Math.floor(index / cols)

      let fromCol = 0
      let fromRow = 0

      if (typeof from === "number") {
        fromCol = from % cols
        fromRow = Math.floor(from / cols)
      } else if (Array.isArray(from)) {
        fromCol = from[0] * (cols - 1)
        fromRow = from[1] * (rows - 1)
      } else if (from === "center") {
        fromCol = (cols - 1) / 2
        fromRow = (rows - 1) / 2
      } else if (from === "last") {
        fromCol = cols - 1
        fromRow = rows - 1
      } else if (from === "random") {
        fromCol = Math.random() * (cols - 1)
        fromRow = Math.random() * (rows - 1)
      }

      const dx = Math.abs(col - fromCol)
      const dy = Math.abs(row - fromRow)

      if (axis === "x") {
        position = dx
      } else if (axis === "y") {
        position = dy
      } else {
        position = Math.sqrt(dx * dx + dy * dy)
      }
    } else {
      // 1D Stagger
      if (typeof from === "number") {
        position = Math.abs(index - from)
      } else if (from === "last") {
        position = total - 1 - index
      } else if (from === "center") {
        const center = (total - 1) / 2
        position = Math.abs(center - index)
      } else if (from === "random") {
        position = Math.random() * (total - 1)
      } else {
        position = index
      }
    }

    if (reversed) {
      position = total - 1 - position
    }

    let calculated: number

    if (Array.isArray(value)) {
      const startParsed = parseUnitValue(value[0])
      const endParsed = parseUnitValue(value[1])
      const maxDist = total > 1 ? total - 1 : 1
      const progress = Math.min(1, Math.max(0, position / maxDist))
      const diff = endParsed.num - startParsed.num
      calculated = start + startParsed.num + progress * diff

      if (modifier) {
        return modifier(calculated)
      }
      return startParsed.unit
        ? `${calculated}${startParsed.unit}`
        : calculated
    }

    const valParsed = parseUnitValue(value)
    calculated = start + position * valParsed.num

    if (modifier) {
      return modifier(calculated)
    }

    return valParsed.unit ? `${calculated}${valParsed.unit}` : calculated
  }
}

// -----------------------------------------------------------------------------
// Interactive Stagger Grid Component
// -----------------------------------------------------------------------------

export interface AnimeStaggerGridProps
  extends React.HTMLAttributes<HTMLDivElement> {
  columns?: number
  rows?: number
  activeColor?: string
  baseColor?: string
  from?: StaggerFrom
  staggerDelay?: number
  waveSpeed?: number
  autoPlay?: boolean
}

export function AnimeStaggerGrid({
  columns = 12,
  rows = 6,
  activeColor = "#10b981",
  from = "center",
  staggerDelay = 50,
  autoPlay = true,
  className,
  ...props
}: AnimeStaggerGridProps) {
  const [clickedIndex, setClickedIndex] = React.useState<number | null>(null)
  const total = columns * rows

  const triggerOrigin = clickedIndex !== null ? clickedIndex : from

  const staggerFn = React.useMemo(() => {
    return stagger(staggerDelay, {
      grid: [columns, rows],
      from: triggerOrigin,
    })
  }, [columns, rows, triggerOrigin, staggerDelay])

  const [animTrigger, setAnimTrigger] = React.useState(0)

  React.useEffect(() => {
    if (!autoPlay) return
    const interval = setInterval(() => {
      setAnimTrigger((prev) => prev + 1)
    }, 2800)
    return () => clearInterval(interval)
  }, [autoPlay])

  const handleTileClick = (index: number) => {
    setClickedIndex(index)
    setAnimTrigger((prev) => prev + 1)
  }

  return (
    <div
      data-slot="anime-stagger-grid"
      className={cn(
        "grid gap-1.5 p-4 rounded-3xl border border-zinc-200 bg-zinc-950 shadow-2xl dark:border-zinc-800 select-none",
        className
      )}
      style={{
        gridTemplateColumns: `repeat(${columns}, minmax(0, 1fr))`,
      }}
      {...props}
    >
      {Array.from({ length: total }).map((_, index) => {
        const delay = Number(staggerFn(index, total)) || 0

        return (
          <div
            key={`${index}-${animTrigger}`}
            onClick={() => handleTileClick(index)}
            className="aspect-square w-full rounded-lg bg-zinc-800/80 cursor-pointer transition-transform hover:scale-110 active:scale-95 shadow-xs"
            style={{
              animation: `staggerWave 1.4s cubic-bezier(0.22, 1, 0.36, 1) ${delay}ms both`,
            }}
          >
            <style jsx>{`
              @keyframes staggerWave {
                0% {
                  transform: scale(0.6);
                  background-color: #27272a;
                  box-shadow: none;
                }
                35% {
                  transform: scale(1.18);
                  background-color: ${activeColor};
                  box-shadow: 0 0 16px ${activeColor}80;
                }
                70% {
                  transform: scale(1);
                  background-color: #3f3f46;
                  box-shadow: none;
                }
                100% {
                  transform: scale(1);
                  background-color: #27272a;
                  box-shadow: none;
                }
              }
            `}</style>
          </div>
        )
      })}
    </div>
  )
}
